import{_ as l,l as o,o as e,c as s,v as t,p as n,x as r,d as h,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Hull-White 树校准","description":"","frontmatter":{"title":"Hull-White 树校准","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hw-tree-calib.md","filePath":"quant/hw-tree-calib.md","lastUpdated":1789023840000}'),d={name:"quant/hw-tree-calib.md"};function u(E,a,c,_,D,B){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="hull-white-树校准" tabindex="-1">Hull-White 树校准 <a class="header-anchor" href="#hull-white-树校准" aria-label="Permalink to &quot;Hull-White 树校准&quot;">​</a></h1><div class="epigraph"><p>在重组三叉树上，每一时间层用 Arrow–Debreu 价格反解位移，使零息债精确等于市场折现；均值回复靠中心节点与概率调整维持，波动与回复速度则留给 cap 或 swaption。</p><footer>—— Hull and White, Numerical Procedures for Implementing Term Structure Models I: One-Factor Models, Journal of Derivatives, 1994</footer></div><p><a href="/quant/hull-white">Hull-White</a> 写出连续动态 \\(dr=(\\theta(t)-ar)\\mathrm{d}t+\\sigma\\mathrm{d}W\\)，以及由市场瞬时远期闭合的 \\(\\theta(t)\\)。<a href="/quant/binomial-tree">二叉树与三叉树</a> 写 CRR 与三态格子的一般构造。本篇只写 <strong>1994 年那棵可校准的三叉树</strong>：节点怎么布置、每层怎么钉债券、概率何时掉出 \\([0,1]\\)、\\(a,\\sigma\\) 分段时如何保持重组。不把 Vasicek 均衡故事重讲，不把 \\(\\theta(t)\\) 的微分方程再推一遍当作实现——树上的位移是离散版的 \\(\\theta\\)，由折现因子逐层解出，与闭合公式在步长有限时并不自动相等。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连续 \\(\\theta(t)\\) 含 \\(f(0,t)\\) 的导数，折线远期会让漂移尖刺，再传到美式价格。树的路线是：不要先微分市场曲线，而在每个时间层 \\(t_i\\) 引入位移 \\(\\alpha_i\\)，使从今日出发的折现</p> \\[P(0,t_{i+1})=\\sum_j Q_{i,j}\\exp\\bigl(-r_{i,j}\\Delta t\\bigr) \\]<p>精确等于市场，其中 \\(Q_{i,j}\\) 是到达节点 \\((i,j)\\) 的 Arrow–Debreu 价格。\\(\\alpha_i\\) 通常进入短端 \\(r_{i,j}=\\alpha_i+k\\Delta r\\cdot j\\) 一类网格。问题是：网格间距 \\(\\Delta r\\) 与时间步 \\(\\Delta t\\) 如何匹配 \\(\\sigma\\) 与 \\(a\\)，使分叉概率落在 \\([0,1]\\) 且节点重组；以及 caplet 校准 \\(\\sigma(t)\\) 时如何在层上放分段波动而不拆散树。</p><p>一因子树校准的是曲线与短端波动，不是斜率。用 cap 校准再给 swaption 定价，是经典失败，模型篇已强调；本篇假设你已选对仪器，讨论数值如何把该仪器钉住。</p><h3 id="重组、均值回复与负概率" tabindex="-1">重组、均值回复与负概率 <a class="header-anchor" href="#重组、均值回复与负概率" aria-label="Permalink to &quot;重组、均值回复与负概率&quot;">​</a></h3><p>无回复的 Ho–Lee 三叉（或二项）中心沿远期走，重组简单。Hull–White 有 \\(-ar\\)：远离均值的节点应更可能往回跳。Hull–White 用改变中心分叉（或调整三态概率）保持回复。若 \\(a\\Delta t\\) 过大或 \\(\\Delta r\\) 与 \\(\\sigma\\sqrt{\\Delta t}\\) 不匹配，对称概率公式会给出负值。标准修复：拉大 \\(\\Delta r\\)、缩短 \\(\\Delta t\\)，或切换到「中心节点跟踪局部均值」的索引，使相对位移保持 \\(O(\\sigma\\sqrt{\\Delta t})\\)。负概率不是「市场无套利破了」，是格子与过程不匹配。</p><p><span class="marginnote">树上解出的 \\(\\alpha_i\\) 序列不是货币政策路径，与连续 \\(\\theta(t)\\) 一样含凸性。把它画成隐含加息轨迹，会把 Jensen 与离散误差讲成央行意图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>几何。</strong> 时间步常取等距或按工作日；空间步 \\(\\Delta r\\) 取 \\(\\sigma\\sqrt{3\\Delta t}\\) 一类，使三态匹配局部均值与方差（Kamrad–Ritchken / Hull–White 惯例）。节点 \\(j\\) 从中心向下上各延伸足够覆盖 \\(\\sigma\\sqrt{T}\\) 的数个标准差，过宽浪费，过窄截断分布、期权偏贵或偏便宜。</p><p><strong>前向归纳。</strong> \\(Q_{0,0}=1\\)。对每层 \\(i\\)，在未知 \\(\\alpha_i\\) 下写出一层折现，解标量方程使 \\(P(0,t_{i+1})\\) 等于市场——通常单调，牛顿或二分一次即够。然后用风险中性概率把 \\(Q\\) 推到 \\(i+1\\) 层。全程不用数值微分市场 \\(f\\)。输入曲线应先修成光滑远期，否则 \\(\\alpha_i\\) 仍会锯齿，美式倒推振荡。</p><p><strong>期权校准。</strong> \\(a\\) 与 \\(\\sigma\\) 常数时，用一组 caplet 或共终端欧式 swaption 做一维或二维搜索，每组参数重建树（或用闭合 Jamshidian 做欧式，树留给美式）。分段 \\(\\sigma(t_k)\\)：在对应时间层改 \\(\\Delta r\\) 或改分叉方差，重组要求相邻层网格可嵌套。实务常保持 \\(\\Delta r\\) 全局固定、只改概率与 \\(\\alpha\\)，把分段 \\(\\sigma\\) 的不匹配吸收进轻微的概率非对称。校准目标必须与定价同一棵树：用闭合公式校准 \\(\\sigma\\)、用树给 Bermudan 定价，离散误差会变成假的提前行权溢价。</p><h3 id="arrow–debreu-与关键利率" tabindex="-1">Arrow–Debreu 与关键利率 <a class="header-anchor" href="#arrow–debreu-与关键利率" aria-label="Permalink to &quot;Arrow–Debreu 与关键利率&quot;">​</a></h3><p>\\(Q_{i,j}\\) 是模型内的状态价格。对市场曲线关键点做 1bp 扰动，重解整条 \\(\\alpha\\)，再重定价，得到关键利率久期。一因子下这些久期几乎共线，树再密也变不成 2s10s 对冲器。树校准的验收是：全部输入零息债误差在离散容差内；选定的 cap / swaption 重定价误差在买卖价差内；概率非负；\\(\\alpha_i\\) 无尖刺。斜率产品不在验收清单里。</p>',17)),(e(),n(m,null,{default:r(()=>[p(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Crv%5B%22%E5%B8%82%E5%9C%BA%20P(0%2CT)%20%E5%85%89%E6%BB%91%E8%BF%9C%E6%9C%9F%22%5D%20--%3E%20AD%5B%22%E9%80%90%E5%B1%82%E8%A7%A3%20%CE%B1_i%20%E4%BD%BF%E5%80%BA%E6%8B%9F%E5%90%88%22%5D%0A%20%20Grid%5B%22%CE%94t%2C%20%CE%94r%20%E5%8C%B9%E9%85%8D%20%CF%83%2C%20a%22%5D%20--%3E%20Prob%5B%22%E4%B8%89%E6%80%81%E6%A6%82%E7%8E%87%20%2F%20%E4%B8%AD%E5%BF%83%E8%8A%82%E7%82%B9%22%5D%0A%20%20Prob%20--%3E%20AD%0A%20%20AD%20--%3E%20Tree%5B%22%E9%87%8D%E7%BB%84%20HW%20%E4%B8%89%E5%8F%89%E6%A0%91%22%5D%0A%20%20Cap%5B%22cap%20%E6%88%96%E5%85%B1%E7%BB%88%E7%AB%AF%20swaption%22%5D%20--%3E%20Sig%5B%22%E6%A0%A1%E5%87%86%20a%2C%20%CF%83(t)%22%5D%0A%20%20Sig%20--%3E%20Tree%0A%20%20Tree%20--%3E%20Am%5B%22%E7%BE%8E%E5%BC%8F%20%2F%20Bermudan%20%E5%80%92%E6%8E%A8%22%5D%0A%20%20Tree%20--%3E%20KR%5B%22%E5%85%B3%E9%94%AE%E5%88%A9%E7%8E%87%3A%20%E4%BB%8D%E4%B8%80%E7%BB%B4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无套利在树上的实现是：每个零息债被 Arrow–Debreu 加总钉死，短端在节点之间的分叉匹配高斯方差与均值回复。连续极限下若 \\(\\Delta t\\to 0\\) 且 \\(\\alpha_i\\) 收敛，应回到带 \\(\\theta(t)\\) 的 Hull–White。有限步长时，闭合 \\(\\theta(t)\\) 插入 Euler 模拟，与树的 \\(\\alpha_i\\) 可以对不齐——这是离散方案差，不是两套模型。生产应对欧式债券期权同时跑闭合公式与树，差距随 \\(N\\) 下降，否则实现有 bug。</p><p>均值回复使长端节点的有效波动小于 \\(\\sigma\\sqrt{T}\\)：\\(a\\) 大则树的宽度被压住，这是相对 Ho–Lee 的要点。校准若只盯短 caplet，\\(\\sigma\\) 被抬高，长 Bermudan 会过贵；若只盯长 swaption，短端可能不够。分段 \\(\\sigma(t)\\) 是在一因子约束下硬拟合期限结构波动，过拟合后逐日 \\(\\sigma(t)\\) 会跳，对冲比昨天与今天不在同一过程。正则：分段宜少、或对 \\(\\sigma(t)\\) 加光滑罚。</p><h3 id="与-monte-carlo、pde-的对账" tabindex="-1">与 Monte Carlo、PDE 的对账 <a class="header-anchor" href="#与-monte-carlo、pde-的对账" aria-label="Permalink to &quot;与 Monte Carlo、PDE 的对账&quot;">​</a></h3><p>同一 \\(a,\\sigma,\\theta\\) 的欧拉 MC 在负利率路径、离散漂移上与树不同。美式不能朴素 MC。PDE 与树是近亲（显式三对角 ≈ 三叉），边界条件（\\(r\\to\\pm\\infty\\) 的截断）须对齐。不要用树校准、用 MC 给路径依赖还声称同一 Hull–White：先对欧式对账。两因子 G2++ 树维度上升，重组更难，常改 MC；一因子树的工程价值正在于美式便宜。</p><p><span class="marginnote">Jamshidian 分解给欧式 swaption 闭式，校准欧式不必每次建树。树仍是美式与路径依赖的定价引擎。两套 \\(\\sigma\\) 若分开估，Bermudan 的提前行权溢价不可信。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>负利率在高斯树上自然出现。合同禁止负利率时，位移对数正态或 CIR++ 更合适，不要在 HW 树上事后把负 \\(r\\) 截成零——截断破坏拟合过的债券与期权。多曲线：贴现 OIS 一棵树，预测曲线另建或做基差；用一条 \\(r\\) 同时贴现 LIBOR 支付，是 2014 年以前的错误。微笑：树是高斯短端，caplet 微笑没有；要微笑需局部波动树或 LMM。</p><p>输入曲线的存贮间隔（年、月）与 \\(\\Delta t\\) 不一致时，插值假设（对数线性折现 vs 线性远期）会改变 \\(\\alpha_i\\)。应与交易台曲线惯例一致。节假日与工作日计数影响 \\(\\Delta t\\) 是否均匀，不均匀步长要重推概率公式，不能沿用等距的 \\(\\sigma\\sqrt{3\\Delta t}\\)。</p><p><span class="marginnote">Hull–White 1990 是连续模型；1994 是数值程序。引用「Hull–White 树」应指向 1994 与节点规则，而不是只写 1990 的 \\(\\theta(t)\\) 公式。</span></p><p><span class="marginnote">一因子树对贴现类美式往往够用；对 CMS 斜率、曲率香草不够用。校准得再精确，也只精确在那个一维模态上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>1994 三叉树用每层 Arrow–Debreu 反解位移 \\(\\alpha_i\\)，拟合全部输入零息债，无需数值微分 \\(f(0,t)\\)。</li><li>\\(\\Delta r\\) 与 \\(\\Delta t\\) 须匹配 \\(a,\\sigma\\)，否则负概率；均值回复靠中心节点或概率调整。</li><li>\\(a,\\sigma\\) 用 cap 或共终端 swaption 校准，且欧式闭合与美式树必须同一参数、对账欧式。</li><li>分段 \\(\\sigma(t)\\) 可拟合波动期限结构，但过拟合会破坏对冲稳定。</li><li>关键利率仍一维；斜率产品、微笑、多曲线要在树外加结构。</li><li>出处：Hull and White, <em>Journal of Derivatives</em>, 1994；连续模型见 Hull and White, <em>RFS</em>, 1990；Ho and Lee, 1986；一般三叉见 Boyle、Kamrad–Ritchken。</li></ul>',13))])}const b=l(d,[["render",u]]);export{A as __pageData,b as default};
